function withQuery(path: string, query: Record<string, string | number | boolean>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    params.set(key, String(value));
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listT02Invoices(
  query: Record<string, string | number | boolean>,
): Promise<T02InvoiceListItem[]> {
  const res = await apiClient.get<BffResponse<T02InvoiceListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getT02Invoice(sttRec: string): Promise<T02Invoice> {
  const res = await apiClient.get<BffResponse<T02Invoice>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createT02Invoice(body: T02InvoiceWrite): Promise<T02Invoice> {
  const res = await apiClient.post<BffResponse<T02Invoice>>(BASE, body);
  return unwrap(res);
}

export async function updateT02Invoice(sttRec: string, body: T02InvoiceWrite): Promise<T02Invoice> {
  const res = await apiClient.put<BffResponse<T02Invoice>>(`${BASE}/${encodeURIComponent(sttRec)}`, body);
  return unwrap(res);
}
