import React, { useEffect, useState } from 'react';
import {
  Button,
  Input,
  LeaveConfirmModal,
  Select,
  dispatchAppToast,
  useDirtyTracking,
  useFormLeaveGuard,
} from '@linm-soft-org/linm-web-common-components';
import { useParams, useSearchParams } from 'react-router-dom';
import { DocumentFormHeader } from '../../../components/layout/DocumentFormHeader';
import { useInAppNavigate } from '../../../router/useInAppNavigate';
import { useAppDispatch } from '../../../store/hooks';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import {
  createT02Invoice,
  getT02Invoice,
  updateT02Invoice,
  type T02Invoice,
  type T02InvoiceWrite,
  type T02InvoiceWriteLine,
} from '../../../services/kt/t02Invoices';
import df from '../../../styles/documentForm.module.css';

const LEAVE_MESSAGE = 'Có thay đổi chưa được lưu. Đóng form sẽ mất dữ liệu đã nhập.';

interface LineState {
  sttRec0?: string;
  soSeri: string;
  maKh: string;
  tenKh: string;
  diaChi: string;
  maSoThue: string;
  tenVt: string;
  tTienNt2: string;
  tTien2: string;
  maThue: string;
  thueSuat: string;
  tThueNt: string;
  tThue: string;
  tkThueCo: string;
  tkDu: string;
  ghiChu: string;
  slTd: string;
  maVv: string;
  maHd: string;
  maPhi: string;
  maTtln: string;
  maTtcp: string;
  maBp: string;
}

interface FormState {
  maGd: string;
  maPost: string;
  maQuyen: string;
  ngayCt: string;
  ngayLct: string;
  soCt: string;
  maNt: string;
  tyGia: string;
  dienGiai: string;
  lines: LineState[];
}

type LineKey = keyof Omit<LineState, 'sttRec0'>;

const LINE_COLUMNS: Array<{
  key: LineKey;
  header: string;
  maxLength?: number;
  decimal?: boolean;
  readOnly?: boolean;
}> = [
  { key: 'soSeri', header: 'Số Seri', maxLength: 30 },
  { key: 'maKh', header: 'Đối tượng', maxLength: 30 },
  { key: 'tenKh', header: 'Tên đối tượng', maxLength: 200 },
  { key: 'diaChi', header: 'Địa chỉ', maxLength: 200 },
  { key: 'maSoThue', header: 'Mã số thuế', maxLength: 30 },
  { key: 'tenVt', header: 'Tên hàng hoá', maxLength: 200 },
  { key: 'tTienNt2', header: 'Tiền hàng', decimal: true },
  { key: 'tTien2', header: 'Tiền VND', decimal: true, readOnly: true },
  { key: 'maThue', header: 'VAT', maxLength: 10 },
  { key: 'thueSuat', header: '%', decimal: true, readOnly: true },
  { key: 'tThueNt', header: 'Thuế', decimal: true },
  { key: 'tThue', header: 'Thuế VND', decimal: true, readOnly: true },
  { key: 'tkThueCo', header: 'Tk Thuế', maxLength: 30 },
  { key: 'tkDu', header: 'Tk Đ.ứng', maxLength: 30 },
  { key: 'ghiChu', header: 'Ghi chú', maxLength: 200 },
  { key: 'slTd', header: 'Sl Td', decimal: true },
  { key: 'maVv', header: 'V.Việc', maxLength: 30 },
  { key: 'maHd', header: 'Hợp đồng', maxLength: 30 },
  { key: 'maPhi', header: 'khoản mục', maxLength: 30 },
  { key: 'maTtln', header: 'Trung tâm lợi nhuận', maxLength: 30 },
  { key: 'maTtcp', header: 'Trung tâm chi phí', maxLength: 30 },
  { key: 'maBp', header: 'Phòng ban', maxLength: 30 },
];

function today(): string {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
}

function emptyLine(): LineState {
  return {
    soSeri: '',
    maKh: '',
    tenKh: '',
    diaChi: '',
    maSoThue: '',
    tenVt: '',
    tTienNt2: '0',
    tTien2: '0',
    maThue: '',
    thueSuat: '0',
    tThueNt: '0',
    tThue: '0',
    tkThueCo: '',
    tkDu: '',
    ghiChu: '',
    slTd: '0',
    maVv: '',
    maHd: '',
    maPhi: '',
    maTtln: '',
    maTtcp: '',
    maBp: '',
  };
}

function emptyForm(): FormState {
  const date = today();
  return {
    maGd: '2',
    maPost: '3',
    maQuyen: '',
    ngayCt: date,
    ngayLct: date,
    soCt: '',
    maNt: '',
    tyGia: '',
    dienGiai: '',
    lines: [],
  };
}

function dateInput(value: string | null | undefined): string {
  return value ? value.slice(0, 10) : '';
}

function numText(value: number | null | undefined): string {
  if (value === null || value === undefined || Number.isNaN(value)) return '0';
  return String(value);
}

function num(value: string): number {
  const text = value.trim();
  if (!text) return 0;
  const parsed = Number(text.replace(',', '.'));
  return Number.isFinite(parsed) ? parsed : 0;
}

function fromInvoice(dto: T02Invoice, keepKeys: boolean): FormState {
  return {
    maGd: dto.maGd || '2',
    maPost: dto.maPost || '3',
    maQuyen: dto.maQuyen ?? '',
    ngayCt: dateInput(dto.ngayCt),
    ngayLct: dateInput(dto.ngayLct),
    soCt: dto.soCt ?? '',
    maNt: dto.maNt ?? '',
    tyGia: dto.tyGia === 0 ? '0' : numText(dto.tyGia),
    dienGiai: dto.dienGiai ?? '',
    lines: (dto.lines ?? []).map(line => ({
      sttRec0: keepKeys ? line.sttRec0 : undefined,
      soSeri: line.soSeri ?? '',
      maKh: line.maKh ?? '',
      tenKh: line.tenKh ?? '',
      diaChi: line.diaChi ?? '',
      maSoThue: line.maSoThue ?? '',
      tenVt: line.tenVt ?? '',
      tTienNt2: numText(line.tTienNt2),
      tTien2: numText(line.tTien2),
      maThue: line.maThue ?? '',
      thueSuat: numText(line.thueSuat),
      tThueNt: numText(line.tThueNt),
      tThue: numText(line.tThue),
      tkThueCo: line.tkThueCo ?? '',
      tkDu: line.tkDu ?? '',
      ghiChu: line.ghiChu ?? '',
      slTd: numText(line.slTd),
      maVv: line.maVv ?? '',
      maHd: line.maHd ?? '',
      maPhi: line.maPhi ?? '',
      maTtln: line.maTtln ?? '',
      maTtcp: line.maTtcp ?? '',
      maBp: line.maBp ?? '',
    })),
  };
}

function toWrite(form: FormState, keepKeys: boolean): T02InvoiceWrite {
  return {
    maCt: 'T02',
    maGd: form.maGd,
    maPost: form.maPost,
    maQuyen: form.maQuyen.trim(),
    ngayCt: form.ngayCt || null,
    ngayLct: form.ngayLct || null,
    soCt: form.soCt.trim(),
    maNt: form.maNt.trim(),
    tyGia: num(form.tyGia),
    dienGiai: form.dienGiai.trim(),
    lines: form.lines.map(line => {
      const row: T02InvoiceWriteLine = {
        soSeri: line.soSeri.trim(),
        maKh: line.maKh.trim(),
        tenKh: line.tenKh.trim(),
        diaChi: line.diaChi.trim(),
        maSoThue: line.maSoThue.trim(),
        tenVt: line.tenVt.trim(),
        tTienNt2: num(line.tTienNt2),
        tTien2: num(line.tTien2),
        maThue: line.maThue.trim(),
        thueSuat: num(line.thueSuat),
        tThueNt: num(line.tThueNt),
        tThue: num(line.tThue),
        tkThueCo: line.tkThueCo.trim(),
        tkDu: line.tkDu.trim(),
        ghiChu: line.ghiChu.trim(),
        slTd: num(line.slTd),
        maVv: line.maVv.trim(),
        maHd: line.maHd.trim(),
        maPhi: line.maPhi.trim(),
        maTtln: line.maTtln.trim(),
        maTtcp: line.maTtcp.trim(),
        maBp: line.maBp.trim(),
      };
      if (keepKeys && line.sttRec0) row.sttRec0 = line.sttRec0;
      return row;
    }),
  };
}

const T02FormPage: React.FC = () => {
  const { sttRec } = useParams();
  const [searchParams] = useSearchParams();
  const navigate = useInAppNavigate();
  const dispatch = useAppDispatch();
  const copyFrom = searchParams.get('copyFrom') ?? '';
  const isView = Boolean(sttRec) && searchParams.get('mode') === 'view';
  const isNew = !sttRec;
  const { onDirtyChange, guardedNavigate, leaveConfirmModalProps } = useFormLeaveGuard({ message: LEAVE_MESSAGE });
  const { markDirty, markClean } = useDirtyTracking(isView ? undefined : onDirtyChange);

  const [form, setForm] = useState<FormState>(emptyForm);
  const [selectedLine, setSelectedLine] = useState(-1);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [loaded, setLoaded] = useState(isNew && !copyFrom);

  useEffect(() => {
    if (!sttRec && !copyFrom) {
      setForm(emptyForm());
      setSelectedLine(-1);
      setLoaded(true);
      setError('');
      markClean();
      return;
    }
    const key = sttRec || copyFrom;
    let cancelled = false;
    setLoading(true);
    setError('');
    void getT02Invoice(key)
      .then(dto => {
        if (cancelled) return;
        setForm(fromInvoice(dto, Boolean(sttRec)));
        setSelectedLine(-1);
        setLoaded(true);
        markClean();
      })
      .catch(err => {
        if (cancelled) return;
        setLoaded(false);
        setError(getApiErrorMessage(err, 'Không tìm thấy cập nhập hóa đơn GTGT đầu ra'));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [sttRec, copyFrom]);

  const edit = (patch: Partial<FormState>) => {
    setForm(prev => ({ ...prev, ...patch }));
    if (!isView) markDirty();
  };

  const editLine = (index: number, key: LineKey, value: string) => {
    setForm(prev => ({
      ...prev,
      lines: prev.lines.map((line, i) => (i === index ? { ...line, [key]: value } : line)),
    }));
    if (!isView) markDirty();
  };

  const addLine = () => {
    setForm(prev => {
      const lines = [...prev.lines, emptyLine()];
      setSelectedLine(lines.length - 1);
      return { ...prev, lines };
    });
    if (!isView) markDirty();
  };

  const removeLine = () => {
    if (selectedLine < 0) return;
    setForm(prev => ({
      ...prev,
      lines: prev.lines.filter((_, index) => index !== selectedLine),
    }));
    setSelectedLine(-1);
    if (!isView) markDirty();
  };

  const onSave = async () => {
    setSaving(true);
    setError('');
    try {
      const body = toWrite(form, Boolean(sttRec));
      const saved = isNew
        ? await createT02Invoice(body)
        : await updateT02Invoice(sttRec as string, body);
      markClean();
      dispatchAppToast(dispatch, { type: 'success', message: 'Đã lưu cập nhập hóa đơn GTGT đầu ra' });
      setForm(fromInvoice(saved, true));
      navigate(`/kt/t02/${saved.sttRec}`);
    } catch (err) {
      const message = getApiErrorMessage(err, 'Lưu thất bại');
      setError(message);
      dispatchAppToast(dispatch, { type: 'error', message });
    } finally {
      setSaving(false);
    }
  };

  const title = isView
    ? 'Xem cập nhập hóa đơn GTGT đầu ra'
    : isNew
      ? 'Thêm cập nhập hóa đơn GTGT đầu ra'
      : 'Sửa cập nhập hóa đơn GTGT đầu ra';
  const locked = isView;
  const showGrid = loaded && !error;

  return (
    <div className={df.page} data-testid="ct-t02-form">
      <LeaveConfirmModal {...leaveConfirmModalProps} />
      <DocumentFormHeader
        testIdPrefix="ct-t02"
        title={title}
        isNew={isNew}
        isReadOnly={isView}
        saving={saving}
        saveLabel="Lưu"
        saveEditLabel="Lưu"
        onBack={() => guardedNavigate(() => navigate('/kt/t02'))}
        onSave={showGrid && !isView ? () => { void onSave(); } : undefined}
      />
      {error ? <div className={df.errorBanner}>{error}</div> : null}
      {loading ? <div className={df.loading}>Đang tải...</div> : null}
      {showGrid ? (
        <>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Chứng từ</h2>
            <div className={df.row4}>
              <Select label="Loại giao dịch" data-testid="ct-t02-field-maGd" disabled={locked} value={form.maGd} options={[{ value: '2', label: 'Kê khai thuế' }]} onChange={event => edit({ maGd: event.target.value })} />
              <Select label="Mức xử lý" data-testid="ct-t02-field-maPost" disabled={locked} value={form.maPost} options={[{ value: '3', label: 'Lập chứng từ' }, { value: '9', label: 'Kê khai thuế' }]} onChange={event => edit({ maPost: event.target.value })} />
              <div>
                <label className={df.label}>Quyền số</label>
                <Input maxLength={30} disabled={locked} data-testid="ct-t02-field-maQuyen" value={form.maQuyen} onChange={event => edit({ maQuyen: event.target.value })} />
              </div>
              <div>
                <label className={df.label}>Ngày C.từ</label>
                <Input type="date" disabled={locked} data-testid="ct-t02-field-ngayCt" value={form.ngayCt} onChange={event => edit({ ngayCt: event.target.value })} />
              </div>
              <div>
                <label className={df.label}>Ngày lập</label>
                <Input type="date" disabled={locked} data-testid="ct-t02-field-ngayLct" value={form.ngayLct} onChange={event => edit({ ngayLct: event.target.value })} />
              </div>
              <div>
                <label className={df.label}>Số C.từ</label>
                <Input maxLength={30} disabled={locked} data-testid="ct-t02-field-soCt" value={form.soCt} onChange={event => edit({ soCt: event.target.value })} />
              </div>
              <div>
                <label className={df.label}>Ngoại tệ</label>
                <Input maxLength={3} disabled={locked} data-testid="ct-t02-field-maNt" value={form.maNt} onChange={event => edit({ maNt: event.target.value })} />
              </div>
              <div>
                <label className={df.label}>Tỷ giá</label>
                <Input inputMode="decimal" disabled={locked} data-testid="ct-t02-field-tyGia" value={form.tyGia} onChange={event => edit({ tyGia: event.target.value })} />
              </div>
              <div className={df.spanCol2}>
                <label className={df.label}>Diễn giải</label>
                <Input maxLength={200} disabled={locked} data-testid="ct-t02-field-dienGiai" value={form.dienGiai} onChange={event => edit({ dienGiai: event.target.value })} />
              </div>
            </div>
          </section>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Dòng hóa đơn</h2>
            {locked ? null : (
              <div>
                <Button className={df.btnAddLine} data-testid="ct-t02-line-add-btn" onClick={addLine}>Thêm dòng</Button>
                <Button className={df.btnDeleteLine} data-testid="ct-t02-line-remove-btn" disabled={selectedLine < 0} onClick={removeLine}>Xóa dòng</Button>
              </div>
            )}
            <div className={df.tableWrapper}>
              <table className={df.linesTable} data-testid="ct-t02-line-grid">
                <thead>
                  <tr>
                    {LINE_COLUMNS.map(column => (
                      <th key={column.key}>{column.header}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {form.lines.map((line, index) => (
                    <tr
                      key={line.sttRec0 ?? `new-${index}`}
                      aria-selected={index === selectedLine}
                      style={index === selectedLine ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined}
                      onClick={() => setSelectedLine(index)}
                    >
                      {LINE_COLUMNS.map(column => (
                        <td key={column.key}>
                          <Input
                            inputMode={column.decimal ? 'decimal' : undefined}
                            maxLength={column.maxLength}
                            disabled={locked || column.readOnly}
                            data-testid={`ct-t02-line-${index}-${column.key}`}
                            value={line[column.key]}
                            onChange={event => editLine(index, column.key, event.target.value)}
                          />
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        </>
      ) : null}
    </div>
  );
};

export default T02FormPage;
